					return e1.Link == e2.Link && e1.RefID == e2.RefID && e1.Source == e2.Source && slices.Equal(e1.Tags, e2.Tags)
				})
			}) {
				values = append(values, CveContentRefs{
					Type:  ctype,
					Value: cont.References,
				})
			}
		}
	}

	return
}

